function sumPositive(nums) {
  return nums.filter((n) => n > 0).reduce((a, b) => a + b, 0);
}

function squaresOfEvensSum(nums) {
  return nums
    .filter((n) => n % 2 === 0)
    .map((n) => n * n)
    .reduce((a, b) => a + b, 0);
}

function uniqueFlat(...arrays) {
  const merged = arrays.flat();
  return [...new Set(merged)];
}
